import sys

def main():
    data = sys.stdin.read().split()
    status, s, k = data[0], data[1], int(data[2])
    normal = [status[j] == '0' for j in range(26)]
    left = cnt = best = 0
    for right, ch in enumerate(s):
        if normal[ord(ch) - 97]:
            cnt += 1
        while cnt > k:
            if normal[ord(s[left]) - 97]:
                cnt -= 1
            left += 1
        best = max(best, right - left + 1)
    print(best)

